# Connect Law Connect to your Supabase project.
# Usage:
#   .\scripts\setup-supabase-connection.ps1
#   .\scripts\setup-supabase-connection.ps1 -Url "https://xxxx.supabase.co" -AnonKey "eyJ..."

param(
  [string]$Url = "",
  [string]$AnonKey = "",
  [string]$ProjectRef = ""
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

function Write-OverridesFile {
  param([string]$Path, [string]$ProjectUrl, [string]$Key)

  $content = @"
// Generated by scripts/setup-supabase-connection.ps1 — do not commit (gitignored).
// Prefer: flutter run --dart-define=SUPABASE_URL=... --dart-define=SUPABASE_ANON_KEY=...

const String kDevSupabaseUrl = '$ProjectUrl';
const String kDevSupabaseAnonKey = '$Key';
"@

  $dir = Split-Path -Parent $Path
  if (-not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  Set-Content -Path $Path -Value $content -Encoding UTF8
  Write-Host "Wrote $Path" -ForegroundColor Green
}

if (-not $Url) {
  $Url = Read-Host "Supabase Project URL (e.g. https://abcdefgh.supabase.co)"
}
$Url = $Url.Trim().TrimEnd("/")

if (-not $AnonKey) {
  $AnonKey = Read-Host "Supabase anon / publishable key"
}
$AnonKey = $AnonKey.Trim()

if (-not $Url -or -not $AnonKey) {
  throw "URL and anon key are required."
}

if ($Url -notmatch "^https://[a-z0-9]+\.supabase\.co$") {
  Write-Warning "URL format looks unusual: $Url (expected https://YOUR_REF.supabase.co)"
}

if (-not $ProjectRef -and $Url -match "https://([a-z0-9]+)\.supabase\.co") {
  $ProjectRef = $Matches[1]
}

Write-Host "`nTesting connection..." -ForegroundColor Cyan
try {
  $null = Invoke-RestMethod -Uri "$Url/auth/v1/settings" -Headers @{ apikey = $AnonKey } -TimeoutSec 20
  Write-Host "Supabase project is reachable." -ForegroundColor Green
}
catch {
  throw "Could not reach Supabase at $Url - check URL, key, and network. $($_.Exception.Message)"
}

$paths = @(
  (Join-Path $repoRoot "lib\supabase\supabase_local_overrides.dart"),
  (Join-Path $repoRoot "client_export\lib\supabase\supabase_local_overrides.dart")
)

foreach ($p in $paths) {
  Write-OverridesFile -Path $p -ProjectUrl $Url -Key $AnonKey
}

Write-Host "`nDone. Run the app with any launch config — Supabase loads from supabase_local_overrides.dart." -ForegroundColor Green
Write-Host "Debug log should show: Supabase initialized ($Url)" -ForegroundColor Gray

if ($ProjectRef) {
  Write-Host "`nOptional — link Supabase CLI for Edge Functions (send-sms):" -ForegroundColor Cyan
  Write-Host "  .\scripts\supabase-cli.ps1 login"
  Write-Host "  .\scripts\supabase-cli.ps1 link --project-ref $ProjectRef"
  Write-Host "  .\scripts\supabase-cli.ps1 functions deploy send-sms --project-ref $ProjectRef"
  Write-Host "`nCreate a public Storage bucket named 'files' in Dashboard > Storage." -ForegroundColor Cyan
}
